  1→package com.danawa.dsearch.server.collections.service.schedule;
  2→
  3→import com.danawa.dsearch.server.clusters.entity.Cluster;
  4→import com.danawa.dsearch.server.clusters.service.ClusterService;
  5→import com.danawa.dsearch.server.collections.entity.Collection;
  6→import com.danawa.dsearch.server.collections.entity.IndexingStep;
  7→import com.danawa.dsearch.server.collections.entity.IndexingInfo;
  8→import com.danawa.dsearch.server.collections.service.CollectionService;
  9→import com.danawa.dsearch.server.collections.service.indexing.IndexingJobManager;
 10→import com.danawa.dsearch.server.collections.service.indexing.IndexingJobService;
 11→import com.danawa.dsearch.server.collections.service.status.StatusService;
 12→import com.danawa.dsearch.server.excpetions.CronParseException;
 13→import com.danawa.dsearch.server.excpetions.IndexingJobFailureException;
 14→import org.apache.commons.lang.NullArgumentException;
 15→import org.slf4j.Logger;
 16→import org.slf4j.LoggerFactory;
 17→import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler;
 18→import org.springframework.scheduling.support.CronTrigger;
 19→import org.springframework.stereotype.Service;
