 27→@Service
 28→public class IndexingScheduler {
 29→    /**
 30→     * 색인 스케쥴을 관리하는 클래스 입니다.
 31→     *
 32→     * 주요 변수는 아래와 같습니다
 33→     * - schedulerMap: 스케쥴링을 관리하는 Map
 34→     * - scheduler: 스케쥴링을 실제로 실행시키는 쓰레드
 35→     */
 36→    private static Logger logger = LoggerFactory.getLogger(IndexingScheduler.class);
 37→    private ConcurrentHashMap<String, ScheduledFuture<?>> schedulerMap = new ConcurrentHashMap<>();
 38→    private final ThreadPoolTaskScheduler scheduler = new ThreadPoolTaskScheduler();
 39→
 40→    private ClusterService clusterService;
 41→    private final CollectionService collectionService;
 42→    private final IndexingJobService indexingJobService;
 43→    private final IndexingJobManager indexingJobManager;
 44→    private final StatusService statusService;
 45→    public IndexingScheduler(ClusterService clusterService,
 46→                             CollectionService collectionService,
 47→                             StatusService statusService,
 48→                             IndexingJobService indexingJobService,
 49→                             IndexingJobManager indexingJobManager){
 50→        this.indexingJobService = indexingJobService;
 51→        this.indexingJobManager = indexingJobManager;
 52→        this.collectionService = collectionService;
 53→        this.statusService = statusService;
 54→        this.clusterService = clusterService;
 55→        this.scheduler.initialize();
 56→    }
 57→
 58→    @PostConstruct
 59→    public void init() {
 60→        // 1. 등록된 모든 클러스터 조회
 61→        List<Cluster> clusterList = clusterService.findAll();
 62→
 63→        int clusterSize = clusterList.size();
 64→
 65→        for (int i = 0; i < clusterSize; i++) {
 66→            Cluster cluster = clusterList.get(i);
 67→            try {
 68→                // 1. 클러스터별로 기존 작업 중인 잡을 다시 등록한다.
 69→                List<Map<String, Object>> documents = statusService.findAll(cluster.getId(), 10000, 0);
 70→
 71→                // 2. 진행 중 문서 중 jobID가 null 인경우와 7일 지난 문서는 무시.
 72→                Calendar calendar = Calendar.getInstance();
 73→                calendar.add(Calendar.DATE, 7);
 74→                long expireStartTime = calendar.getTimeInMillis();
 75→
 76→                // 3. 마지막 인덱싱 내역 확인 후 컬렉션 관리 스케쥴링 등록
 77→                documents.forEach(documentFields -> {
 78→                    try {
 79→                        Map<String, Object> source = documentFields;
 80→
 81→                        // 잡아이디가 없는 문서가 많음... 로컬 실행하여 테스트 데이터 의심...
 82→                        if (source.get("jobId") != null && !"".equals(source.get("jobId"))) {
 83→                            long startTime = (long) source.get("startTime");
 84→
 85→                            if (expireStartTime <= startTime) {
 86→                                UUID clusterId = cluster.getId();
 87→                                String collectionId = (String) source.get("collectionId");
 88→
 89→                                if(!indexingJobManager.isExistInManageQueue(collectionId)) {
 90→                                    Collection collection = collectionService.findById(clusterId, collectionId);
 91→                                    IndexingInfo indexingInfo = makeIndexingStatus(clusterId, source, collection);
 92→                                    indexingJobManager.add(collectionId, indexingInfo, false);
 93→                                    logger.debug("collection register cluster: {}, job: {}, step: {}",
 94→                                            cluster.getName(), collectionId, IndexingStep.valueOf(String.valueOf(source.get("step"))));
 95→                                }
 96→                            }
 97→                        }
 98→                    } catch (Exception e) {
 99→                        logger.error("[INIT ERROR] ", e);
100→                    }
101→                });
102→            } catch (Exception e) {
103→                logger.error("[INIT ERROR]", e);
104→            }
105→
106→            // 컬렉션의 스케쥴이 enabled 이면 다시 스케쥴을 등록한다.
107→            registerAll(cluster.getId());
108→            logger.debug("init finished");
109→        }
110→    }
111→
112→    private IndexingInfo makeIndexingStatus(UUID clusterId, Map<String, Object> source, Collection collection){
113→        Collection.Launcher launcher = collection.getLauncher();
114→        String jobId = String.valueOf(source.getOrDefault("jobId", ""));
115→        String index = (String) source.get("index");
116→        long startTime = (long) source.get("startTime");
117→        IndexingStep step = IndexingStep.valueOf(String.valueOf(source.get("step")));
118→
119→        IndexingInfo indexingInfo = new IndexingInfo();
120→        indexingInfo.setClusterId(clusterId);
121→        indexingInfo.setIndex(index);
122→        indexingInfo.setStartTime(startTime);
123→        if (launcher != null) {
124→            indexingInfo.setIndexingJobId(jobId);
125→            indexingInfo.setScheme(launcher.getScheme());
126→            indexingInfo.setHost(launcher.getHost());
127→            indexingInfo.setPort(launcher.getPort());
128→        }
129→        indexingInfo.setAutoRun(true);
130→        indexingInfo.setCurrentStep(step);
131→        indexingInfo.setNextStep(new ArrayDeque<>());
132→        indexingInfo.setRetry(50);
133→        indexingInfo.setCollection(collection);
134→        return indexingInfo;
135→    }
136→
137→    /**
138→     * 모든 스케줄 삭제
139→     * @param clusterId
140→     */
141→    public void unregisterAll(UUID clusterId){
142→        if(clusterId == null) throw new NullArgumentException("");
143→
144→        for(String key : schedulerMap.keySet()){
145→            if(isRegistered(key, clusterId)){
146→                logger.info("스케줄 제거, clusterId: {}, scheduled key: {}", clusterId, key);
147→                unregister(key);
148→            }
149→        }
150→    }
151→
152→    /**
153→     * 컬렉션에 등록된 많은 크론잡을 스케줄에서 제거한다
154→     * @param clusterId
155→     * @param collectionId
156→     */
157→    private void unregister(UUID clusterId, String collectionId){
158→        Iterator<String> keys = schedulerMap.keySet().iterator();
159→
160→        while (keys.hasNext()){
161→            String key = keys.next();
162→
163→            if(isRegistered(key, clusterId, collectionId)){
164→                unregister(key);
165→            }
166→        }
167→    }
168→
169→    /**
170→     * 키로 등록된 크론잡을 제거한다
171→     * @param key
172→     */
173→    private void unregister(String key){
174→        ScheduledFuture<?> future = schedulerMap.get(key);
175→        future.cancel(true);
176→        schedulerMap.remove(key);
177→    }
178→
179→
180→    /**
181→     * 키가 지울수 있는 키인지 확인한다
182→     * @param key
183→     * @param clusterId
184→     * @return
185→     */
186→    private boolean isRegistered(String key, UUID clusterId){
187→        String prefix = clusterId.toString();
188→        if(key.startsWith(prefix)){
189→            return true;
190→        }
191→        return false;
192→    }
193→
194→    /**
195→     * 키가 지울수 있는 키인지 확인한다
196→     * @param key
197→     * @param clusterId
198→     * @param collectionId
199→     * @return
200→     */
201→    private boolean isRegistered(String key, UUID clusterId, String collectionId){
202→        String prefix = String.format("%s-%s", clusterId, collectionId);
203→
204→        if(key.startsWith(prefix)){
205→            return true;
206→        }
207→        return false;
208→    }
209→
210→    /**
211→     * 스케줄을 리셋해서 등록한다
212→     * @param clusterId
213→     * @param collectionId
214→     */
215→    public void reload(UUID clusterId, String collectionId){
216→        unregister(clusterId, collectionId); // 기존 스케줄을 전부 지우고
217→        register(clusterId, collectionId); //새로 스케줄을 등록한다
218→    }
219→
220→    /**
221→     * 클러스터 내에 있는 모든 스케줄이 활성화된 컬렉션들에 대해 스케줄 매니저에 등록한다
222→     * @param clusterId
223→     */
224→    public void registerAll(UUID clusterId){
225→        if(clusterId == null) throw new NullArgumentException("");
226→
227→        try {
228→            /** 컬렉션의 스케쥴이 enabled 이면 다시 스케쥴을 등록한다. */
229→            List<Collection> collectionList = collectionService.findAll(clusterId);
230→            if (collectionList != null) {
231→                collectionList.forEach(collection -> {
232→                    try {
233→                        if(collection.isScheduled()) {
234→                            register(clusterId, collection.getId(), collection.getCron());
235→                        }
236→                    } catch (Exception e) {
237→                        logger.error("[Register schedule ERROR] ", e);
238→                    }
239→                });
240→            }
241→        } catch (Exception e) {
242→            logger.error("[Register schedule ERROR]", e);
243→        }
244→    }
245→
246→    /**
247→     * 클러스터 내에 있는 컬렉션 한개에 대해 스케줄을 등록한다
248→     * @param clusterId
249→     * @param collectionId
250→     */
251→    public void register(UUID clusterId, String collectionId){
252→        if(clusterId == null) throw new NullArgumentException("");
253→
254→        try {
255→            /** 컬렉션의 스케쥴이 enabled 이면 다시 스케쥴을 등록한다. */
256→            Collection collection = collectionService.findById(clusterId, collectionId);
257→
258→            try {
259→                if(collection.isScheduled()) {
260→                    String crons = collection.getCron();
261→                    register(clusterId, collection.getId(), crons);
262→                }
263→            } catch (Exception e) {
264→                logger.error("[Register schedule ERROR] ", e);
265→            }
266→        } catch (Exception e) {
267→            logger.error("[Register schedule ERROR]", e);
268→        }
269→    }
270→
271→    /**
272→     * 모든 스케줄을 읽는다.
273→     * @return
274→     */
275→    public List<String> getScheduleList(){
276→        List<String> result = new ArrayList<>();
277→
278→        for (String key : schedulerMap.keySet() ){
279→            result.add(key);
280→        }
281→
282→        return result;
283→    }
284→
285→    /**
286→     * 스케줄 키 생성 함수
287→     * @param clusterId
288→     * @param collectionId
289→     * @param cron
290→     * @return
291→     */
292→    private String makeScheduleKey(UUID clusterId, String collectionId, String cron){
293→        return String.format("%s-%s-%s", clusterId.toString(), collectionId, cron);
294→    }
295→
296→    /**
297→     * 크론잡 스케줄 등록
298→     * @param clusterId
299→     * @param collectionId
300→     * @param crons
301→     */
302→    private void register(UUID clusterId, String collectionId, String crons) throws CronParseException {
303→        String[] cronList = collectionService.getCronList(crons);
304→        for(String cron : cronList){
305→            String scheduledKey = makeScheduleKey(clusterId, collectionId, cron);
306→            logger.info("Schedule Register  ClusterId: {}, CollectionId: {}, Cron: {}", clusterId, collectionId, cron);
307→
308→            schedulerMap.put(scheduledKey, Objects.requireNonNull(scheduler.schedule(() -> {
309→                try {
310→                    // 변경사항이 있을수 있으므로, 컬렉션 정보를 새로 가져온다.
311→                    Collection registerCollection = collectionService.findById(clusterId, collectionId);
312→                    IndexingInfo indexingInfo = indexingJobManager.getManageQueue(registerCollection.getId());
313→
314→                    if (indexingInfo != null) {
315→                        return;
316→                    }
317→
318→                    registerCollection.setAutoRun(true);
319→                    IndexingInfo status = indexingJobService.indexingAndExpose(clusterId, registerCollection);
320→                    indexingJobManager.add(registerCollection.getId(), status);
321→                } catch (IndexingJobFailureException | IOException e) {
322→                    logger.error("[INIT ERROR] ", e);
323→                }
324→            }, new CronTrigger("0 " + cron))));
325→        }
326→    }
327→}
