  1→package com.danawa.dsearch.server.collections.service.indexing;
  2→
  3→import com.danawa.dsearch.server.collections.entity.IndexerStatus;
  4→import com.danawa.dsearch.server.collections.entity.Collection;
  5→import com.danawa.dsearch.server.collections.entity.IndexingStep;
  6→import com.danawa.dsearch.server.collections.entity.IndexingInfo;
  7→import com.danawa.dsearch.server.collections.service.indexer.IndexerClient;
  8→import com.danawa.dsearch.server.collections.service.history.HistoryService;
  9→import com.danawa.dsearch.server.collections.service.status.StatusService;
 10→import com.danawa.dsearch.server.excpetions.IndexingJobFailureException;
 11→import com.danawa.dsearch.server.notice.AlertService;
 12→import com.danawa.dsearch.server.utils.TimeUtils;
 13→import org.slf4j.Logger;
 14→import org.slf4j.LoggerFactory;
 15→import org.springframework.beans.factory.annotation.Value;
 16→import org.springframework.scheduling.annotation.Scheduled;
 17→import org.springframework.stereotype.Component;
 18→
 19→import java.io.IOException;
 20→import java.util.*;
 21→import java.util.concurrent.ConcurrentHashMap;
 22→
 23→@Component
 24→public class IndexingJobManager {
 25→    /**
 26→     * 인덱싱하는 과정 및 결과를 관리하는 객체 입니다.
 27→     * 외부 혹은 내부 인덱서와 통신 및 해당 Job에 대한 삭제 및 조회의 책임을 갖습니다
 28→     * 또한, 중간 과정들을 로깅할수 있는 객체로 넘기는 책임을 갖습니다
 29→     *
 30→     * manageQueue는 실질적으로 indexing 되는 과정을 관리합니다
 31→     * lookupQueue는 나중에 조회가 들어왔을 시 결과를 저장해두는 큐입니다.
 32→     * deleteQueue는 색인이 끝난 후 manageQueue에서 해당 내용을 제거하는데 쓰이는 큐입니다.
 33→     */
 34→
 35→    private static final Logger logger = LoggerFactory.getLogger(IndexingJobManager.class);
 36→
 37→
 38→    // 색인 관리 큐
 39→    // key: collection id,  value: Indexing status
 40→    private ConcurrentHashMap<String, IndexingInfo> manageQueue = new ConcurrentHashMap<>();
 41→    // 디서치 인덱서가 상태 조회 할 때 쓰는 큐
 42→    private ConcurrentHashMap<String, IndexingInfo> lookupQueue = new ConcurrentHashMap<>();
 43→    // 색인 관리 큐에서 제거 용도 임시 저장소
 44→    private Set<String> deleteQueue = Collections.newSetFromMap(new ConcurrentHashMap<String, Boolean>());
 45→
 46→
 47→    private IndexingJobService indexingJobService;
 48→    private StatusService indexStatusService;
 49→    private HistoryService indexHistoryService;
 50→    private IndexerClient indexerClient;
 51→    private AlertService alertService;
 52→
 53→    private long timeout;
 54→
 55→    public IndexingJobManager(IndexingJobService indexingJobService,
 56→                              IndexerClient indexerClient,
 57→                              StatusService indexStatusService,
 58→                              HistoryService indexHistoryService,
 59→                              AlertService alertService,
 60→                              @Value("${dsearch.timeout}") long timeout) {
 61→        this.timeout = timeout;
 62→        this.indexStatusService = indexStatusService;
 63→        this.indexHistoryService = indexHistoryService;
 64→        this.indexingJobService = indexingJobService;
 65→        this.alertService = alertService;
 66→        this.indexerClient = indexerClient;
 67→    }
 68→
 69→    @Scheduled(fixedDelay = 1000)
 70→    private void manageIndexingStatus() {
 71→        if (manageQueue.size() == 0) return;
 72→
 73→        Iterator<Map.Entry<String, IndexingInfo>> entryIterator = manageQueue.entrySet().iterator();
 74→
 75→        entryIterator.forEachRemaining(entry -> { // key == collectionId
 76→            String collectionId = entry.getKey();
 77→            IndexingInfo indexingInfo = entry.getValue();
 78→            IndexingStep currentStep = indexingInfo.getCurrentStep();
 79→            logger.info("clusterId={}, index={}, step={}", indexingInfo.getClusterId(), indexingInfo.getIndex(), currentStep.name());
 80→
 81→            try {
 82→                if (currentStep == null) {
 83→                    deleteQueue.add(collectionId);
 84→                    logger.error("index: {}, NOT Matched Step..", indexingInfo.getIndex());
 85→                    throw new IndexingJobFailureException("다음 진행 내용이 없습니다.");
 86→                } else if (currentStep == IndexingStep.FULL_INDEX || currentStep == IndexingStep.DYNAMIC_INDEX) {
 87→                    processIndexStep(indexingInfo, collectionId);
 88→                } else if (currentStep == IndexingStep.EXPOSE) {
 89→                    processExposeStep(indexingInfo, collectionId);
 90→                }
 91→                processOnTimeout(indexingInfo, collectionId);
 92→            } catch (IndexingJobFailureException|IOException e) {
 93→                logger.error("{}", e);
 94→                processRetry(indexingInfo, collectionId);
 95→            }
 96→        });
 97→
 98→        deleteInScheduleQueue(); // scheduleQueue 키 삭제는 여기서
 99→    }
100→
101→    private void processRetry(IndexingInfo indexingInfo, String collectionId){
102→        IndexingStep currentStep = indexingInfo.getCurrentStep();
103→        String status = indexingInfo.getStatus();
104→
105→        if (indexingInfo.getRetry() > 0) {
106→            indexingInfo.setRetry(indexingInfo.getRetry() - 1);
107→            logger.error("현재 재시도 중 입니다.. index:{}, count: {}", indexingInfo.getIndex(), indexingInfo.getRetry());
108→        } else {
109→            if("STOP".equalsIgnoreCase(status)){
110→                createErrorHistoryAndUpdateStatus(indexingInfo, false);
111→            }else if (currentStep == IndexingStep.FULL_INDEX || currentStep == IndexingStep.DYNAMIC_INDEX) {
112→                createErrorHistoryAndUpdateStatus(indexingInfo, false);
113→                indexerClient.deleteJob(indexingInfo);
114→                logger.error("[remove job] retry.. {}", indexingInfo.getRetry());
115→            } else {
116→                logger.error("[remove job] retry.. {}", indexingInfo.getRetry());
117→            }
118→            manageQueue.remove(collectionId);
119→        }
120→    }
121→
122→    private void processOnTimeout(IndexingInfo indexingInfo, String collectionId){
123→        if (isTimeout(indexingInfo.getStartTime())){
124→            indexingInfo.setStatus("STOP");
125→            indexingInfo.setEndTime(System.currentTimeMillis());
126→            logger.error("index: {}, Timeout {} hours..", indexingInfo.getIndex(), (timeout / (1000 * 60 * 60)));
127→
128→            indexingJobService.stopIndexing(indexingInfo);
129→            deleteQueue.add(collectionId);
130→            createErrorHistoryAndUpdateStatus(indexingInfo, false);
131→        }
132→    }
133→
134→    private boolean isTimeout(long startTime){
135→        return System.currentTimeMillis() - startTime >= timeout;
136→    }
137→
138→    private void deleteInScheduleQueue(){
139→        for(String collectionId: deleteQueue){
140→            manageQueue.remove(collectionId);
141→            deleteQueue.remove(collectionId);
142→        }
143→    }
144→
145→    private void processExposeStep(IndexingInfo indexingInfo, String collectionId) throws IOException {
146→        // 인덱스 alias 교체
147→        changeIndexAlias(indexingInfo);
148→        // 인덱싱 결과 조회용 큐에 적재
149→        updateLookupQueue(collectionId, "SUCCESS");
150→        // 혹시나 있을 인덱싱 중지
151→        indexingJobService.stopIndexing(indexingInfo);
152→        // 기존 latest status 변경
153→        indexStatusService.update(indexingInfo, "SUCCESS");
154→        // 로깅
155→        indexingInfo.setCurrentStep(IndexingStep.FULL_INDEX);
156→        indexHistoryService.create(indexingInfo, "SUCCESS");
157→        // 큐에서 삭제
158→        deleteQueue.add(collectionId);
159→    }
160→
161→    private void changeIndexAlias(IndexingInfo indexingInfo) {
162→        UUID clusterId = indexingInfo.getClusterId();
163→        Collection collection = indexingInfo.getCollection();
164→        while(true){
165→            try{
166→                indexingJobService.expose(clusterId, collection, indexingInfo.getIndex());
167→            } catch (IOException e) {
168→                TimeUtils.sleep(1000);
169→                continue;
170→            }
171→            break;
172→        }
173→    }
174→
175→    private void updateLookupQueue(String collectionId, String status){
176→        IndexingInfo indexingInfo = manageQueue.get(collectionId);
177→        indexingInfo.setStatus(status);
178→        indexingInfo.setEndTime(System.currentTimeMillis());
179→        lookupQueue.put(collectionId, indexingInfo);
180→    }
181→
182→    private void createErrorHistoryAndUpdateStatus(IndexingInfo indexingInfo, boolean checkIndex){
183→        String status = "";
184→        if (checkIndex) {
185→            status = indexerClient.getStatus(indexingInfo).toString();
186→            indexHistoryService.create(indexingInfo, status);
187→        } else {
188→            status = "ERROR";
189→            String docSize = "0";
190→            String store = "0";
191→            indexHistoryService.create(indexingInfo, docSize, status, store);
192→        }
193→        indexStatusService.update(indexingInfo, status);
194→
195→        String currentStep = indexingInfo.getCurrentStep().name();
196→        if ("FULL_INDEX".equalsIgnoreCase(currentStep) || "DYNAMIC_INDEX".equalsIgnoreCase(currentStep)) {
197→            alertService.send(String.format("%s 인덱스의 색인이 실패하였습니다.", indexingInfo.getIndex()));
198→        } else {
199→            alertService.send(String.format("%s 인덱스의 %s가 실패하였습니다.", indexingInfo.getIndex(), currentStep));
200→        }
201→    }
202→
203→    public void add(String collectionId, IndexingInfo indexingInfo) throws IndexingJobFailureException {
204→        IndexingInfo registerIndexingInfo = getManageQueue(collectionId);
205→        if (registerIndexingInfo != null) {
206→            throw new IndexingJobFailureException("Duplicate Collection Indexing");
207→        }
208→        if (indexingInfo.getClusterId() == null) {
