238→    private void processIndexStep(IndexingInfo indexingInfo, String collectionId) throws IOException{
239→        UUID clusterId = indexingInfo.getClusterId();
240→        String index = indexingInfo.getIndex();
241→        Collection collection = indexingInfo.getCollection();
242→        long endTime = System.currentTimeMillis();
243→
244→        IndexerStatus status = indexerClient.getStatus(indexingInfo);
245→
246→        if (status == IndexerStatus.SUCCESS){
247→            indexingInfo.setEndTime(endTime);
248→
249→            indexStatusService.update(indexingInfo, "SUCCESS");
250→            IndexingStep nextStep = indexingInfo.getNextStep().poll();
251→
252→            logger.info("Indexing {} ==> clusterId: {}, index: {}, collectionId", status, clusterId, indexingInfo.getIndex(), collectionId);
253→            indexingJobService.changeRefreshInterval(clusterId, collection, index); // 색인 끝나면 refresh_interval 변경
254→
255→            if (nextStep != null) {
256→                // 교체까지 있는 색인
257→                indexStatusService.create(indexingInfo, "RUNNING"); // Expose가 남아 있기 때문에 status 추가
258→                indexingInfo.setCurrentStep(nextStep); // 교체 단계 셋팅 (안하면 Null Pointer Exception)
259→                manageQueue.put(collectionId, indexingInfo); // 교체 단계가 있으므로 다시 스케줄에 넣는다.
260→            }else{
261→                // 단순 색인
262→                deleteQueue.add(collectionId);
263→                updateLookupQueue(collectionId, "SUCCESS");
264→            }
265→
266→            indexerClient.deleteJob(indexingInfo);
267→            // refresh interval 을 수행한 뒤 60초 대기 시간 추가
268→            // 다큐먼트 카운트가 전부 업데이트 되기 전에 cat/indices 조회 시 진행 중인 값으로 가져옴
269→            TimeUtils.sleep(60000);
270→        }else if (status == IndexerStatus.ERROR || status == IndexerStatus.STOP){
271→            logger.info("Indexing {} ==> clusterId: {}, index: {}, collectionId", status, clusterId, indexingInfo.getIndex(), collectionId);
272→            indexingInfo.setEndTime(endTime);
273→            createErrorHistoryAndUpdateStatus(indexingInfo, true);
274→
275→            deleteQueue.add(collectionId);
276→            updateLookupQueue(collectionId, status.toString());
277→            indexerClient.deleteJob(indexingInfo);
278→        } else if(status == IndexerStatus.RUNNING){
279→            indexingInfo.setStatus(IndexerStatus.RUNNING.toString());
280→            updateLookupQueue(collectionId, status.toString());
281→            manageQueue.put(collectionId, indexingInfo);
282→        } else { // UNKNOWN
283→            deleteQueue.add(collectionId);
284→        }
285→    }
