 85→    /**
 86→     * 소스를 읽어들여 ES 색인에 입력하는 작업.
 87→     * indexer를 외부 프로세스로 실행한다.
 88→     *
 89→     * @return IndexingStatus
 90→     */
 91→    private IndexingInfo indexing(UUID clusterId, Collection collection, Queue<IndexingStep> actionSteps) throws IndexingJobFailureException {
 92→        IndexingInfo status = null;
 93→        Collection.Index targetIndex = null;
 94→        IndexingStep currentStep = actionSteps.poll();
 95→
 96→        try{
 97→            // 1. 대상 인덱스 찾기.
 98→            targetIndex = getTargetIndex(clusterId, collection);
 99→
100→            // 2. 인덱스 설정 변경.
101→            configureIndexSettings(clusterId, targetIndex);
102→
103→            // 3. 런처 파라미터 변환 작업
104→            Map<String, Object> requestBody = makeRequestBodyToIndexer(clusterId, collection, targetIndex);
105→
106→            // 4. indexer 색인 전송
107→            String indexingJobId = requestToIndexer(requestBody, collection);
108→
109→            // 5. Indexing Status 셋팅하기
110→            status = makeIndexingStatus(clusterId, collection, targetIndex, indexingJobId, currentStep, actionSteps);
111→
112→            logger.info("인덱싱 시작, clusterId={}, collection={}, index={}", clusterId, collection.getBaseId(), status.getIndex());
113→        }catch (IndexingJobFailureException|ConvertYamlException e) {
114→            sendIndexingError(collection, targetIndex, e.getMessage());
115→            throw new IndexingJobFailureException(e.getMessage());
116→        }
117→
118→        return status;
119→    }
