121→    private Collection.Index getTargetIndex(UUID clusterId, Collection collection) throws IndexingJobFailureException {
122→        // 1. alias 가져오기
123→        String aliasString = getAliasString(clusterId);
124→        // 2. alias Json 변환
125→        // {
126→        //     "alias": "...",
127→        //     "index": "..."
128→        // }
129→        List<Map<String, Object>> aliasMap = new Gson().fromJson(aliasString, List.class);
130→        // 3. 현재 컬렉션의 alias가 있는지 찾기
131→        String collectionName = collection.getBaseId();
132→        if (isExistCollectionNameInAliases(aliasMap, collectionName)){
133→            // 3-1. 있다면 파싱해서 주기 
134→            return parseTargetIndex(aliasMap, collection);
135→        }else{
136→            // 3-2. 없다면 디폴트(IndexA)로 주기
137→            return getDefaultIndex(collection);
138→        }
139→    }
140→    private boolean isExistCollectionNameInAliases(List<Map<String, Object>> aliasMap, String baseId){
141→        for (Map<String, Object> item : aliasMap) {
142→            if (item.get("alias").equals(baseId)) {
143→                return true;
144→            }
145→        }
146→
147→        return false;
148→    }
