170→    private Collection.Index parseTargetIndex(List<Map<String, Object>> aliasMap, Collection collection) {
171→        String baseId = collection.getBaseId();
172→        Collection.Index targetIndex = collection.getIndexA();
173→
174→        for (Map<String, Object> item : aliasMap) {
175→            if (item.get("alias").equals(baseId)) {
176→
177→                String currentIndex = (String) item.get("index");
178→                String suffix = currentIndex.substring(currentIndex.length() - 2);
179→
180→                if (suffix.equals("-a")) {
181→                    targetIndex = collection.getIndexB();
182→                } else if (suffix.equals("-b")) {
183→                    targetIndex = collection.getIndexA();
184→                }
185→                break;
186→            }
187→        }
188→
189→        return targetIndex;
190→    }
