380→    private void changeAliasWithTargetIndex(UUID clusterId, Collection collection, String targetIndex) throws IOException{
381→        IndicesAliasesRequest request = new IndicesAliasesRequest();
382→
383→        String baseId = collection.getBaseId();
384→        Collection.Index indexA = collection.getIndexA();
385→        Collection.Index indexB = collection.getIndexB();
386→
387→        String nameOfindexA = indexA.getIndex() != null ? indexA.getIndex() : "" ;
388→        String nameOfindexB = indexB.getIndex() != null ? indexB.getIndex() : "" ;
389→
390→        String toAddIndex = getIndexToAddAlias(nameOfindexA, nameOfindexB, targetIndex);
391→        String toRemoveIndex = getIndexToRemoveAlias(nameOfindexA, nameOfindexB, targetIndex);
392→
393→        try {
394→            request.addAliasAction(new IndicesAliasesRequest.
395→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
396→                    .index(toAddIndex).alias(baseId));
397→            request.addAliasAction(new IndicesAliasesRequest.
398→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.REMOVE)
399→                    .index(toRemoveIndex).alias(baseId));
400→            elasticsearchFactoryWrapper.updateAliases(clusterId, request);
401→        } catch (Exception e) {
402→            request = new IndicesAliasesRequest();
403→            request.addAliasAction(new IndicesAliasesRequest.
404→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
405→                    .index(toAddIndex).alias(baseId));
406→            // 교체
407→            elasticsearchFactoryWrapper.updateAliases(clusterId, request);
408→        }
409→    }
410→
411→    private String getIndexToAddAlias(String indexA, String indexB, String targetIndex){
412→        if (indexA.equals(targetIndex)) {
413→            return indexA;
414→        } else {
415→            return indexB;
416→        }
417→    }
418→
419→    private String getIndexToRemoveAlias(String indexA, String indexB, String targetIndex){
420→        if (indexA.equals(targetIndex)) {
421→            return indexB;
422→        } else {
423→            return indexA;
424→        }
425→    }
426→
427→    private String changeAliasWithoutTargetIndex(UUID clusterId, Collection collection) throws IOException {
428→        IndicesAliasesRequest request = new IndicesAliasesRequest();
429→
430→        String baseId = collection.getBaseId();
431→        Collection.Index indexA = collection.getIndexA();
432→        Collection.Index indexB = collection.getIndexB();
433→
434→        String targetIndex;
435→
436→        if (isExistsIfOnlyIndexB(collection)) {
437→            // 1. -b 인덱스만 있을 경우
438→            request.addAliasAction(new IndicesAliasesRequest.
439→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
440→                    .index(indexB.getIndex()).alias(baseId));
441→            targetIndex = indexB.getIndex();
442→        } else if (isExistsIfOnlyIndexA(collection)) {
443→            // 2. -a 인덱스만 있을 경우
444→            request.addAliasAction(new IndicesAliasesRequest.
445→                    AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
446→                    .index(indexA.getIndex()).alias(baseId));
447→            targetIndex = indexA.getIndex();
448→        } else {
449→            // 3. -a, -b 인덱스가 있을 경우
450→            // 인덱스 히스토리 로그를 찾아 최근에 성공한 인덱스를 찾는다
451→            targetIndex = findRecentlyIndexingSuccessIndex(clusterId, indexA.getIndex(), indexB.getIndex());
452→
453→            if ("".equals(targetIndex)) {
454→                // 3.1) -a, -b 인덱스 둘다 있지만 alias가 셋팅이 되지 않은 경우
455→                request.addAliasAction(new IndicesAliasesRequest.
456→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
457→                        .index(indexA.getIndex()).alias(baseId));
458→
459→                targetIndex = indexA.getIndex();
460→            } else {
461→                // 3.2) -a, -b 인덱스 둘다 있지만 alias가 셋팅이 되어 있는 경우
462→                String addIndex = getIndexToAddAlias(indexA.getIndex(), indexB.getIndex(), targetIndex);
463→                String removeIndex = getIndexToRemoveAlias(indexA.getIndex(), indexB.getIndex(), targetIndex);
464→
465→                request.addAliasAction(new IndicesAliasesRequest.
466→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.ADD)
467→                        .index(addIndex).alias(baseId));
468→                request.addAliasAction(new IndicesAliasesRequest.
469→                        AliasActions(IndicesAliasesRequest.AliasActions.Type.REMOVE)
470→                        .index(removeIndex).alias(baseId));
471→            }
472→        }
473→
474→        // Alias 교체
475→        elasticsearchFactoryWrapper.updateAliases(clusterId, request);
476→        return targetIndex;
477→    }
478→
479→    private boolean isExistsIfOnlyIndexA(Collection collection){
480→        Collection.Index indexA = collection.getIndexA();
481→        Collection.Index indexB = collection.getIndexB();
482→        return indexA.getUuid() != null && indexB.getUuid() == null;
483→    }
484→
485→    private boolean isExistsIfOnlyIndexB(Collection collection){
486→        Collection.Index indexA = collection.getIndexA();
487→        Collection.Index indexB = collection.getIndexB();
488→        return indexA.getUuid() == null && indexB.getUuid() != null;
489→    }
490→
491→    private String findRecentlyIndexingSuccessIndex(UUID clusterId, String indexA, String indexB) throws IOException {
492→        // index_history 조회하여 마지막 인덱스, 색인 완료한 인덱스 검색.
493→        QueryBuilder queryBuilder = new BoolQueryBuilder()
494→                .must(new MatchQueryBuilder("jobType", "FULL_INDEX"))
495→                .must(new MatchQueryBuilder("status", "SUCCESS"))
496→                .should(new MatchQueryBuilder("index", indexA))
497→                .should(new MatchQueryBuilder("index", indexB))
498→                .minimumShouldMatch(1);
499→        SearchRequest searchRequest = new SearchRequest()
500→                .indices(indexHistory)
501→                .source(new SearchSourceBuilder().query(queryBuilder)
502→                        .size(1)
503→                        .from(0)
504→                        .sort("endTime", SortOrder.DESC)
505→                );
506→
507→        SearchResponse searchResponse = elasticsearchFactoryWrapper.search(clusterId, searchRequest);
508→        SearchHit[] searchHits = searchResponse.getHits().getHits();
509→
510→        if(searchHits.length == 1){
511→            // index_history 조회하여 대상 찾음.
512→            Map<String, Object> source = searchHits[0].getSourceAsMap();
513→            String targetIndex = (String) source.get("index");
514→            return targetIndex;
515→        }else{
516→            return "";
517→        }
518→    }
