 86→    public void create(UUID clusterId, Collection collection) throws IOException, DuplicatedUserException {
 87→        try(RestHighLevelClient client = elasticsearchFactory.getClient(clusterId)) {
 88→            SearchRequest searchRequest = new SearchRequest().indices(collectionIndex);
 89→
 90→            BoolQueryBuilder boolQueryBuilder = QueryBuilders.boolQuery();
 91→            boolQueryBuilder = boolQueryBuilder.minimumShouldMatch(1);
 92→            List<QueryBuilder> list = boolQueryBuilder.should();
 93→            list.add(QueryBuilders.termQuery("baseId.keyword", collection.getBaseId()));
 94→
 95→            searchRequest.source(new SearchSourceBuilder().query(boolQueryBuilder));
 96→
 97→            //추후 변경 예정
 98→//            searchRequest.source(new SearchSourceBuilder().query(new TermQueryBuilder("baseId", collection.getBaseId())));
 99→            SearchResponse searchResponse = client.search(searchRequest, RequestOptions.DEFAULT);
100→            if (searchResponse.getHits().getTotalHits().value > 0) {
101→                throw new DuplicatedUserException("duplicate baseId");
102→            }
103→
104→            String indexNameA = collection.getBaseId() + indexSuffixA;
105→            String indexNameB = collection.getBaseId() + indexSuffixB;
106→
107→            Collection.Index indexA = new Collection.Index();
108→            Collection.Index indexB = new Collection.Index();
109→            indexA.setIndex(indexNameA);
110→            indexB.setIndex(indexNameB);
111→            collection.setIndexA(indexA);
112→            collection.setIndexB(indexB);
113→            client.index(new IndexRequest()
114→                            .index(collectionIndex)
115→                            .source(build(collection))
116→                    , RequestOptions.DEFAULT);
117→
118→            AcknowledgedResponse response = client.indices()
119→                    .putTemplate(new PutIndexTemplateRequest(collection.getBaseId()).patterns(Arrays.asList(indexNameA, indexNameB)), RequestOptions.DEFAULT);
120→            if(response.isAcknowledged()){
121→                logger.info("collection [{}] is created", collection.getBaseId());
122→            }
123→        }
124→    }
