 17→    /**
 18→     * 컬렉션의 색인 서비스를 담당하는 객체 입니다.
 19→     * 색인 서비스에는 아래와 같은 타입이 있습니다.
 20→     * - 전체 (All) : 색인 + 교체를 한꺼번에 담당합니다
 21→     * - 색인 (Indexing) : 파일/DB 등 여러 타입을 ES로 색인합니다
 22→     * - 교체 (Expose) : 해당 컬렉션의 Alias를 바꾸어 줍니다.
 23→     * - 중지 (Stop-Indexing) : 색인 중 중지를 하고 싶을때 사용합니다.
 24→     * - 다중 색인(Sub-Start) : 여러 색인 파일을 동시에 하고 싶을때 사용합니다.
 25→     */
 26→    private static Object obj = new Object();
 27→
 28→    private static final Logger logger = LoggerFactory.getLogger(IndexingService.class);
 29→
 30→    private final IndexingJobManager indexingJobManager;
 31→    private final IndexingJobService indexingJobService;
 32→
 33→    public IndexingService(IndexingJobService indexingJobService,
 34→                           IndexingJobManager indexingJobManager){
 35→        this.indexingJobService = indexingJobService;
 36→        this.indexingJobManager = indexingJobManager;
 37→    }
 38→    public Map<String, Object> processIndexingJob(
 39→            UUID clusterId,
 40→            Collection collection,
 41→            IndexingAction actionType,
 42→            String groupSeq) {
 43→
 44→        Map<String, Object> response = new HashMap<>();
 45→
 46→        switch (actionType){
 47→            case ALL:
 48→                synchronized (obj) {
 49→                    try{
 50→                        IndexingInfo status = startIndexingAndExpose(clusterId, collection);
 51→                        response.put("indexingStatus", status);
 52→                        response.put("result", "success");
 53→                    } catch (IndexingJobFailureException e) {
 54→                        indexingJobManager.setQueueStatus(collection.getId(), "ERROR");
 55→                        response.put("result", "fail");
 56→                    }
 57→                }
 58→                break;
 59→            case INDEXING:
 60→                synchronized (obj) {
 61→                    try {
 62→                        IndexingInfo status = startIndexing(clusterId, collection);
 63→                        response.put("indexingStatus", status);
 64→                        response.put("result", "success");
 65→                    } catch (IndexingJobFailureException e) {
 66→                        indexingJobManager.setQueueStatus(collection.getId(), "ERROR");
 67→                        response.put("result", "fail");
 68→                    }
 69→                }
 70→                break;
 71→            case EXPOSE:
 72→                synchronized (obj) {
 73→                    try{
 74→                        startExpose(clusterId, collection);
 75→                        response.put("result", "success");
 76→                    } catch (IOException | IndexingJobFailureException e) {
 77→                        indexingJobManager.setQueueStatus(collection.getId(), "ERROR");
 78→                        response.put("result", "fail");
 79→                    }
 80→                }
 81→                break;
 82→            case STOP_INDEXING:
 83→                synchronized (obj) {
 84→                    IndexingInfo indexingInfo = stopIndexing(collection);
 85→                    if(indexingInfo == null){
 86→                        response.put("message", "try to stop indexing but not found indexing...");
 87→                    }else{
 88→                        response.put("message", "stopped");
 89→                        response.put("indexingStatus", indexingInfo);
 90→                    }
 91→
 92→                    response.put("result", "success");
 93→                }
 94→                break;
 95→            case SUB_START:
 96→                synchronized (obj) {
 97→                    IndexingInfo status = startGroupIndexing(collection, groupSeq);
 98→                    logger.info("GroupIndexing 확인,  {} {}", collection, groupSeq);
 99→                    if (status == null) {
100→                        response.put("result", "fail");

100→                        response.put("result", "fail");
101→                    } else {
102→                        response.put("indexingStatus", status);
103→                        response.put("result", "success");
104→                    }
105→                }
106→                break;
107→            default:
108→                response.put("message", "Not Found Action. Please Select Action in this list (all / indexing / propagate / expose / stop_indexing / stop_propagation)");
109→                response.put("result", "success");
110→        }
111→        return response;
112→    }
