120→    private IndexingInfo startIndexingAndExpose(UUID clusterId, Collection collection) throws IndexingJobFailureException {
121→        String collectionId = collection.getId();
122→        if(isNowIndexing(collectionId)){
123→            throw new IndexingJobFailureException("현재 색인 중...");
124→        }
125→
126→        IndexingInfo status = indexingJobService.indexingAndExpose(clusterId, collection);
127→        indexingJobManager.add(collectionId, status);
128→        return status;
129→    }
