131→    private IndexingInfo startIndexing(UUID clusterId, Collection collection) throws IndexingJobFailureException {
132→        String collectionId = collection.getId();
133→        if(isNowIndexing(collectionId)){
134→            throw new IndexingJobFailureException("현재 색인 중...");
135→        }
136→
137→        IndexingInfo status = indexingJobService.indexing(clusterId, collection);
138→        indexingJobManager.add(collectionId, status);
139→        logger.info("indexingJobManager: {}", indexingJobManager.getManageQueue(collectionId));
140→        return status;
